# CSP: Exam schedule without conflicts
students = {"Math": ["Alice", "Bob"], "Physics": ["Bob", "Eve"], "CS": ["Alice", "Eve"]}
schedule = {"Math": "Mon", "Physics": "Tue", "CS": "Wed"}
days = {}
for course, day in schedule.items():
    if day not in days:
        days[day] = []
    days[day].append(course)
for day, courses in days.items():
    status = '✅' if len(courses) == 1 else '❌ CONFLICT'
    print(f"{day}: {courses} {status}")

