# Simple hill climbing: find peak in a landscape
landscape = [1, 3, 7, 9, 6, 4, 2]
current = 0

while True:
    next_pos = current
    if current + 1 < len(landscape) and landscape[current + 1] > landscape[current]:
        next_pos = current + 1
    elif current - 1 >= 0 and landscape[current - 1] > landscape[current]:
        next_pos = current - 1

    if next_pos == current:
        print(f"Peak found at position {current}: value {landscape[current]}")
        break
    current = next_pos
